mapper.select:
SELECT id,name,code,parent_id,sort,status,create_time,update_time FROM org_college
status = #{status}
ORDER BY sort ASC

SELECT id,college_id,name,code,sort,status,create_time,update_time
FROM org_major


        college_id = #{collegeId}


        status = #{status}


ORDER BY sort ASC

SELECT c.id,c.major_id,c.name,c.code,c.sort,c.status,c.grade_year,c.create_time,c.update_time, COUNT(u.id) AS studentCount FROM org_class c LEFT JOIN sys_user u ON c.id = u.class_id AND u.role = 'student' AND u.status = 1
c.major_id = #{majorId}
c.status = #{status}
GROUP BY c.id ORDER BY c.sort ASC
